import {
  reactExtension,
  Banner,
  useApi,
  useSubscription,
} from '@shopify/ui-extensions-react/checkout';

export default reactExtension(
  'purchase.checkout.block.render',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  const {cost} = useApi();

  // Equivalent to the useTotalAmount() hook to subscribe and re-render your extension on changes
  const totalAmount = useSubscription(
    cost.totalAmount,
  );

  return &lt;Banner&gt;{totalAmount.amount}&lt;/Banner&gt;;
}

import {extension} from '@shopify/ui-extensions/checkout';

export default extension(
  'purchase.address-autocomplete.format-suggestion',
  async ({target}) =&gt; {
    // 1. Use the suggestion the buyer selected
    const {selectedSuggestion} = target;

    // 2. Fetch the address parts to format the address
    const {
      address1,
      address2,
      city,
      zip,
      provinceCode,
      countryCode,
    } = await fetch(
      `https://myapp.com/api/fetch-address?id=${selectedSuggestion.id}`,
    );

    // 3. Return a formatted address
    return {
      formattedAddress: {
        address1,
        address2,
        city,
        zip,
        provinceCode,
        countryCode,
      },
    };
  },
);

