import {useState} from 'react';
import {
  reactExtension,
  Banner,
  Checkbox,
  useDeliverySelectionGroups,
  useDeliveryGroupListTarget,
  useApplyMetafieldsChange,
  BlockStack,
} from '@shopify/ui-extensions-react/checkout';

// 1. Choose an extension target
export default reactExtension(
  'purchase.checkout.shipping-option-list.render-after',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  const metafieldNamespace = 'yourAppNamespace';
  const deliveryGroupList =
    useDeliveryGroupListTarget();
  const deliverySelectionGroups =
    useDeliverySelectionGroups();
  const applyMetafieldsChange =
    useApplyMetafieldsChange();
  const [checked, setChecked] = useState(false);

  // 2. Render a UI
  if (!deliveryGroupList) {
    return null;
  }

  const {groupType, deliveryGroups} =
    deliveryGroupList;
  const metafieldKey =
    groupType === 'oneTimePurchase'
      ? 'isGift-oneTimePurchase'
      : 'isGift-subscription';
  const selectedDeliverySelectionGroup =
    deliverySelectionGroups?.find(
      ({selected}) =&gt; selected,
    );

  const groupLabel =
    groupType === 'oneTimePurchase'
      ? 'one time purchase'
      : 'subscription';

  const title =
    deliveryGroups.length &gt; 1
      ? `Your order contains multiple ${groupLabel} shipments.`
      : `Your order contains one ${groupLabel} shipment.`;

  let deliverySelectionGroupInfo = '';
  if (selectedDeliverySelectionGroup) {
    deliverySelectionGroupInfo = ` Items will be delivered with the ${selectedDeliverySelectionGroup.title} delivery selection group.`;
  }

  return (
    &lt;BlockStack spacing="base"&gt;
      &lt;Banner
        status="info"
        title={`${title}${deliverySelectionGroupInfo}`}
      /&gt;
      &lt;Checkbox
        onChange={onCheckboxChange}
        checked={checked}
      &gt;
        The {groupLabel} section contains gifts
      &lt;/Checkbox&gt;
    &lt;/BlockStack&gt;
  );

  // 3. Call API methods to modify the checkout
  async function onCheckboxChange(isChecked) {
    setChecked(isChecked);
    const result = await applyMetafieldsChange({
      type: 'updateMetafield',
      namespace: metafieldNamespace,
      key: metafieldKey,
      value: isChecked ? 'yes' : 'no',
      valueType: 'string',
    });
    console.log(
      'applyMetafieldsChange result',
      result,
    );
  }
}

import {
  extension,
  Banner,
  Checkbox,
  BlockStack,
} from '@shopify/ui-extensions/checkout';

// 1. Choose an extension target
export default extension(
  'purchase.checkout.shipping-option-list.render-after',
  (
    root,
    {
      target,
      deliverySelectionGroups:
        deliverySelectionGroupsSubscription,
      applyMetafieldChange,
    },
  ) =&gt; {
    const metafieldNamespace = 'yourAppNamespace';
    let checkboxShown = false;
    let bannerShown = false;
    let title = '';
    let deliverySelectionGroupInfo = '';

    const blockStack =
      root.createComponent(BlockStack);
    blockStack.updateProps({
      spacing: 'base',
    });
    root.append(blockStack);
    const checkbox =
      root.createComponent(Checkbox);
    const banner = root.createComponent(Banner);
    banner.updateProps({
      status: 'info',
    });

    target.subscribe((deliveryGroupList) =&gt; {
      if (!deliveryGroupList) {
        return;
      }

      const {groupType, deliveryGroups} =
        deliveryGroupList;
      const metafieldKey =
        groupType === 'oneTimePurchase'
          ? 'isGift-oneTimePurchase'
          : 'isGift-subscription';
      const groupLabel =
        deliveryGroupList.groupType ===
        'oneTimePurchase'
          ? 'one time purchase'
          : 'subscription';
      title =
        deliveryGroups.length &gt; 1
          ? `Your order contains multiple ${groupLabel} shipments.`
          : `Your order contains one ${groupLabel} shipment.`;

      banner.updateProps({
        title: `${title}${deliverySelectionGroupInfo}`,
      });
      checkbox.updateProps({
        onChange: (isChecked) =&gt;
          onCheckboxChange(
            isChecked,
            metafieldKey,
          ),
      });
      checkbox.replaceChildren(
        `The ${groupLabel} section contains gifts`,
      );

      // 2. Render a UI
      if (!bannerShown) {
        blockStack.append(banner);
        bannerShown = true;
      }
      if (!checkboxShown) {
        blockStack.append(checkbox);
        checkboxShown = true;
      }
    });

    deliverySelectionGroupsSubscription.subscribe(
      (deliverySelectionGroups) =&gt; {
        const selectedDeliverySelectionGroup =
          deliverySelectionGroups?.find(
            ({selected}) =&gt; selected,
          );
        if (selectedDeliverySelectionGroup) {
          deliverySelectionGroupInfo = ` Items will be delivered with the ${selectedDeliverySelectionGroup.title} delivery selection group.`;
          banner.updateProps({
            title: `${title}${deliverySelectionGroupInfo}`,
          });
        }
      },
    );

    // 3. Call API methods to modify the checkout
    async function onCheckboxChange(
      isChecked,
      metafieldKey,
    ) {
      checkbox.updateProps({
        checked: isChecked,
      });
      const result = await applyMetafieldChange({
        type: 'updateMetafield',
        namespace: metafieldNamespace,
        key: metafieldKey,
        value: isChecked ? 'yes' : 'no',
        valueType: 'string',
      });
      console.log(
        'applyMetafieldChange result',
        result,
      );
    }
  },
);

