            }),
          ],
        ),
      ],
    );

    const disclosureView = root.createComponent(
      View,
      {
        id: 'one',
        padding: ['none', 'base', 'base', 'base'],
      },
      [
        root.createComponent(
          Form,
          {
            onSubmit: () =&gt;
              console.log('onSubmit event'),
          },
          [
            root.createComponent(BlockStack, {}, [
              root.createComponent(
                InlineLayout,
                {
                  columns: ['fill', 'fill'],
                  spacing: 'base',
                },
                [
                  root.createComponent(
                    TextField,
                    {
                      label: 'From',
                      name: 'from0',
                      id: 'from0',
                    },
                  ),
                  root.createComponent(
                    TextField,
                    {
                      label: 'To',
                      name: 'to0',
                      id: 'to0',
                    },
                  ),
                ],
              ),
              root.createComponent(TextField, {
                label: 'Message',
                name: 'message0',
                id: 'message0',
              }),
              root.createComponent(View, {}, [
                root.createComponent(
                  Button,
                  {
                    accessibilityRole: 'submit',
                    kind: 'secondary',
                  },
                  'Save',
                ),
              ]),
            ]),
          ],
        ),
      ],
    );

    const disclosure = root.createComponent(
      Disclosure,
      {
        defaultOpen: 'one',
        onToggle: (open) =&gt;
          console.log('onToggle event', open),
      },
      [pressable, disclosureView],
    );

    const inlineLayout = root.createComponent(
      InlineLayout,
      {
        blockAlignment: 'baseline',
        spacing: 'base',
        columns: ['auto', 'fill', 'auto'],
        padding: 'base',
      },
      [
        root.createComponent(Icon, {
          source: 'profile',
          appearance: 'subdued',
