function Extension() {
  const {applyTrackingConsentChange, ui} =
    useApi();

  const {shouldShowBanner} = useCustomerPrivacy();

  const sheetId = 'sheet-consent';

  const handleConsentChange = async ({
    analytics,
    marketing,
    preferences,
    saleOfData,
  }) =&gt; {
    try {
      const result =
        await applyTrackingConsentChange({
          type: 'changeVisitorConsent',
          analytics,
          marketing,
          preferences,
          saleOfData,
        });

      // Check if operation was successful
      if (result.type === 'success') {
        ui.overlay.close(sheetId);
      } else {
        // Handle failure case here
      }
    } catch (error) {
      // Handle error case here
    }
  };

  return (
    &lt;Sheet
      id={sheetId}
      heading="We value your privacy"
      accessibilityLabel="A sheet that collects privacy consent preferences"
      defaultOpen={shouldShowBanner}
      primaryAction={
        &lt;&gt;
          &lt;Button
            kind="secondary"
            onPress={() =&gt;
              handleConsentChange({
                // values derived from local form state
                analytics: false,
                marketing: false,
                preferences: false,
                saleOfData: false,
              })
            }
          &gt;
            I decline
          &lt;/Button&gt;
          &lt;Button
            kind="secondary"
            onPress={() =&gt;
              handleConsentChange({
                analytics: true,
                marketing: true,
                preferences: true,
                saleOfData: true,
              })
            }
          &gt;
            I agree
          &lt;/Button&gt;
        &lt;/&gt;
      }
      secondaryAction={
        &lt;Button
          kind="plain"
          overlay={
            // Open a settings modal
          }
        &gt;
          Settings
        &lt;/Button&gt;
      }
    &gt;
      &lt;TextBlock&gt;
        This website uses cookies to ensure you
        get the best experience on our website.
        &lt;Link&gt;Privacy Policy&lt;/Link&gt;
      &lt;/TextBlock&gt;
    &lt;/Sheet&gt;
  );
}

